public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String T = sc.next();
    int len = T.length();
    int[][] dp = new int[101][101];
    for (int i = 0; i <= 100; i++) {
        Arrays.fill(dp[i], Integer.MAX_VALUE);
    }

    int n = sc.nextInt();
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        int t = sc.nextInt();
        while (t-- > 0) {
            String th = sc.next();
            for (int j = 0; j <= len; j++) {
                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j]);
                if (j >= th.length() && dp[i - 1][j - th.length()] != Integer.MAX_VALUE && T.startsWith(th, j - th.length())) {
                    dp[i][j] = Math.min(dp[i - 1][j - th.length()] + 1, dp[i][j]);
                }
            }
        }
    }
    System.out.println(dp[n][len] == Integer.MAX_VALUE ? -1 : dp[n][len]);
}

